function positionRangement(adresses, cible) {
  let debut = 0;
  let fin = adresses.length;
  while (debut < fin) {
    const milieu = Math.floor((debut + fin) / 2);
    if (adresses[milieu] < cible) {
      debut = milieu + 1;
    } else {
      fin = milieu;
    }
  }
  return debut;
}

