function capaciteMinimale(poids, k, m) {
  if (poids.length === 0) {
    return 0;
  }
  if (Math.ceil(poids.length / m) > k) {
    return -1;
  }
  const voyages = (capacite) => {
    let total = 1;
    let charge = 0;
    let nombre = 0;
    for (const p of poids) {
      if (charge + p > capacite || nombre === m) {
        total++;
        charge = 0;
        nombre = 0;
      }
      charge += p;
      nombre++;
    }
    return total;
  };
  let bas = 0;
  let haut = 0;
  for (const p of poids) {
    bas = Math.max(bas, p);
    haut += p;
  }
  while (bas < haut) {
    const milieu = Math.floor((bas + haut) / 2);
    if (voyages(milieu) <= k) {
      haut = milieu;
    } else {
      bas = milieu + 1;
    }
  }
  return bas;
}

