def capacite_minimale(poids, k, m):
    if len(poids) == 0:
        return 0
    if (len(poids) + m - 1) // m > k:
        return -1

    def voyages(capacite):
        total = 1
        charge = 0
        nombre = 0
        for p in poids:
            if charge + p > capacite or nombre == m:
                total += 1
                charge = 0
                nombre = 0
            charge += p
            nombre += 1
        return total

    bas = max(poids)
    haut = sum(poids)
    while bas < haut:
        milieu = (bas + haut) // 2
        if voyages(milieu) <= k:
            haut = milieu
        else:
            bas = milieu + 1
    return bas

