def kieme_somme(a, b, k):
    # Combien de paires ont une somme inférieure ou égale à x ?
    def compter(x):
        total = 0
        j = len(b) - 1
        for valeur in a:
            while j >= 0 and valeur + b[j] > x:
                j -= 1
            total += j + 1
        return total

    bas = a[0] + b[0]
    haut = a[-1] + b[-1]
    # La plus petite valeur x pour laquelle au moins k sommes sont <= x.
    while bas < haut:
        milieu = (bas + haut) // 2
        if compter(milieu) >= k:
            haut = milieu
        else:
            bas = milieu + 1
    return bas
